    """
    evaluator = Evaluator(expr)
    evaluator.skip_whitespace()
    return evaluator.expr()

def evaluate(expr: str) -> float:
    """
    Evaluate an arithmetic expression using the Shunting Yard algorithm for parsing
    and a stack-based approach for evaluation. Supports +, -, *, /, parentheses,
    and floating-point numbers.
    """
    def precedence(op: str) -> int:
        if op in ('+', '-'):
            return 1
        if op in ('*', '/'):
            return 2
        return 0

    def apply_operator(operands: list, operator: str) -> None:
        right = operands.pop()
        left = operands.pop()
        if operator == '+':
            operands.append(left + right)
        elif operator == '-':
            operands.append(left - right)
        elif operator == '*':
            operands.append(left * right)
        elif operator == '/':
            operands.append(left / right)

    def evaluate_expression(expression: str) -> float:
        operands = []
        operators = []
        i = 0

        while i < len(expression):
            if expression[i].isspace():
                i += 1
                continue

            if expression[i].isdigit() or expression[i] == '.':
                j = i
                while j < len(expression) and (expression[j].isdigit() or expression[j] == '.'):
                    j += 1
                operands.append(float(expression[i:j]))
                i = j
                continue

            if expression[i] == '(':
                operators.append(expression[i])
                i += 1
                continue

            if expression[i] == ')':
                while operators and operators[-1] != '(':
                    apply_operator(operands, operators.pop())
                operators.pop()  # pop the '('
                i += 1
                continue

            while (operators and precedence(operators[-1]) >= precedence(expression[i])):
                apply_operator(operands, operators.pop())
            operators.append(expression[i])
            i += 1

        while operators:
            apply_operator(operands, operators.pop())

        return operands[0]

    return evaluate_expression(expr)

def tokenize(expr: str):
    """
    Tokenize the expression into numbers, operators, and parentheses.
    """
    tokens = []
    num_buffer = []
    for char in expr:
        if char.isspace():
            continue
        if char.isdigit() or char == '.':
            num_buffer.append(char)
        else:
            if num_buffer:
                tokens.append(float(''.join(num_buffer)))
                num_buffer = []
            if char in "+-*/()":
                tokens.append(char)
    if num_buffer:
        tokens.append(float(''.join(num_buffer)))
    return tokens

def shunting_yard(tokens):
    """
    Convert infix tokens to postfix (Reverse Polish Notation) using the
    Shunting Yard algorithm.
    """
    output = []
    operators = []
    precedence = {'+': 1, '-': 1, '*': 2, '/': 2}

    for token in tokens:
        if isinstance(token, float):
            output.append(token)
        elif token in precedence:
            while (operators and operators[-1] != '(' and
                   precedence[operators[-1]] >= precedence[token]):
                output.append(operators.pop())
            operators.append(token)
        elif token == '(':
            operators.append(token)
        elif token == ')':
            while operators and operators[-1] != '(':
                output.append(operators.pop())
            operators.pop()  # pop the '('

    while operators:
        output.append(operators.pop())

    return output

def evaluate_postfix(postfix):
    """
    Evaluate a postfix (RPN) expression.
    """
    stack = []
    for token in postfix:
        if isinstance(token, float):
            stack.append(token)
        else:
            right = stack.pop()
            left = stack.pop()
            if token == '+':
                stack.append(left + right)
            elif token == '-':
                stack.append(left - right)
            elif token == '*':
                stack.append(left * right)
            elif token == '/':
                stack.append(left / right)
    return stack[0]

def evaluate(expr: str) -> float:
    """
    Evaluate an arithmetic expression using a tokenization approach followed by
    the Shunting Yard algorithm for converting to postfix notation and a simple
    stack-based evaluation of that postfix expression.
    Supports +, -, *, /, parentheses, and floating-point numbers.
    """
    tokens = tokenize(expr)
    postfix = shunting_yard(tokens)
